// Configuration
const config = {
  releaseId: process.env.RELEASE_ID,
  externalId: process.env.EXTERNAL_ID,
  apiKey: process.env.RELEASENOTES_API_KEY,
  projectId: process.env.PROJECT_ID || "9630",
  prTitle: process.env.PR_TITLE || "Untitled PR",
  prBody: process.env.PR_BODY || "",
  openaiApiKey: process.env.OPENAI_API_KEY,
};

// Validate required configuration
function validateConfig() {
  const required = [
    { key: "apiKey", name: "RELEASENOTES_API_KEY" },
    { key: "releaseId", name: "RELEASE_ID" },
    { key: "externalId", name: "EXTERNAL_ID" },
    { key: "openaiApiKey", name: "OPENAI_API_KEY" },
  ];

  const missing = required.filter(({ key, name }) => {
    if (!config[key]) {
      console.error(`❌ ${name} is not set.`);
      return true;
    }
    return false;
  });

  if (missing.length > 0) {
    process.exit(1);
  }
}

// Generate AI summary using OpenAI
async function generateAiSummary(title, body) {
  console.log("🤖 Generating AI summary...");

  try {
    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${config.openaiApiKey}`,
      },
      body: JSON.stringify({
        model: "gpt-4",
        messages: [
          {
            role: "system",
            content:
              'Summarize this pull request for release notes. Be concise and focus on user-facing changes. Include the type of change (e.g., "Fix", "Feature", "Enhancement") at the beginning. Send response in markdown format.',
          },
          {
            role: "user",
            content: `${title}\n\n${body}`,
          },
        ],
        temperature: 0.3,
        max_tokens: 200,
      }),
    });

    if (!response.ok) {
      const error = await response.json();
      throw new Error(
        `OpenAI API error: ${error.error?.message || response.statusText}`
      );
    }

    const data = await response.json();
    const summary = data.choices?.[0]?.message?.content?.trim();

    if (!summary) {
      throw new Error("No summary generated by AI");
    }

    console.log("✅ AI Summary generated successfully");
    return summary;
  } catch (error) {
    console.error("❌ Error generating AI summary:", error.message);
    throw error;
  }
}

// Helper function to make API requests to ReleaseNotes.io
async function makeApiRequest(endpoint, method = "GET", data = null) {
  try {
    const headers = {
      Accept: "application/json",
      "Content-Type": "application/json",
    };

    // Construct full URL with API token
    const url = new URL(endpoint, "https://api.releasenotes.io");
    url.searchParams.append("api_token", config.apiKey);

    const options = {
      method,
      headers,
      body: data ? JSON.stringify(data) : undefined,
    };

    console.log(`\n🌐 Making ${method} request to: ${url.toString()}`);
    if (data) {
      console.log("📤 Payload:", JSON.stringify(data, null, 2));
    }

    const response = await fetch(url.toString(), options);
    const responseText = await response.text();

    let responseData;
    try {
      responseData = responseText ? JSON.parse(responseText) : {};
    } catch (e) {
      console.error(
        "⚠️ Could not parse response as JSON, showing raw response:"
      );
      console.error(responseText);
      throw new Error("Invalid JSON response from server");
    }

    if (!response.ok) {
      console.error(`❌ Error from ReleaseNotes.io (${response.status}):`);
      console.error(JSON.stringify(responseData, null, 2));

      if (response.status === 302) {
        console.error(
          "\n🔴 Authentication failed (302 Redirect). Please check your API key and project ID."
        );
      } else if (response.status === 401) {
        console.error("\n🔴 Unauthorized (401). Please check your API key.");
      } else if (response.status === 404) {
        console.error(
          "\n🔴 Project not found (404). Please check your project ID."
        );
      } else if (response.status >= 500) {
        console.error(
          "\n🔴 Server error. Please try again later or contact support."
        );
      }

      throw new Error(`API request failed with status ${response.status}`);
    }

    return responseData;
  } catch (error) {
    if (error.name === "FetchError") {
      console.error("\n🔴 Network error:", error.message);
      throw new Error(
        "Failed to connect to ReleaseNotes.io. Please check your network connection."
      );
    }
    throw error;
  }
}

// Main execution
(async () => {
  try {
    // Validate configuration first
    validateConfig();

    console.log("🚀 Starting ReleaseNotes.io update process...");
    console.log(`📝 PR Title: ${config.prTitle}`);

    // Generate AI summary
    const summary = await generateAiSummary(config.prTitle, config.prBody);
    console.log(`📋 Generated Summary: ${summary}`);

    //based on commit convention set note type
    // feat, fix, docs, style, refactor, test, chore
    let noteType = "feature";
    if (config.prTitle.startsWith("fix")) {
      noteType = "bugfix";
    } else if (config.prTitle.startsWith("docs")) {
      noteType = "documentation";
    } else if (config.prTitle.startsWith("style")) {
      noteType = "style";
    } else if (config.prTitle.startsWith("refactor")) {
      noteType = "refactor";
    } else if (config.prTitle.startsWith("test")) {
      noteType = "test";
    } else if (config.prTitle.startsWith("chore")) {
      noteType = "update";
    }

    // Prepare the payload for ReleaseNotes.io
    const payload = {
      id: config.releaseId,
      external_id: config.externalId,
      notes: [
        {
          note_type: noteType,
          note_title: `${summary}`,
        },
      ],
    };

    // Push to ReleaseNotes.io
    console.log("\n📤 Creating/Updating release in ReleaseNotes.io...");
    const result = await makeApiRequest(
      `https://api.releasenotes.io/api/v1/projects/${config.projectId}/releases`,
      "POST",
      payload
    );

    console.log("\n✅ Success! Release updated in ReleaseNotes.io");
    console.log(JSON.stringify(result, null, 2));
  } catch (error) {
    console.error("\n❌ Process failed:", error.message);
    process.exit(1);
  }
})();
